961	\toprule
962	\textbf{Domain} & \textbf{Generator pool} \\
963	\midrule
964	C4     & Qwen-1.5B, Pythia-1.4B, LLaMA-3.1-8B \\
965	arXiv  & Qwen-1.5B, Pythia-1.4B, LLaMA-3.1-8B \\
966	Code   & Qwen2.5-7B, LLaMA-3.1-8B, Mistral-7B-v0.3 \\
